      for (const r of held483) if (r.key === key483) return r.entry;
      const entry483 = acquireHair483(HAIR_NATIVE_483(), this.style, tn, q483);
      held483.push({ key: key483, lod: tn, entry: entry483 });
      return entry483;
    })();
