    }

    // ---------------- lean springs: acceleration, braking, turn banking
    {
      const af = clamp(this.kaz, -48, 48), al = clamp(this.kax, -48, 48);
      const g = 1 - air * 0.75;
      const lp = walkLean(this, 'pitch', af, g, dt) ?? spr(sp, S_LEANP, clamp(af * 0.0075, -0.36, 0.3) * g, 2.2, 0.4, dt);
      const lr = walkLean(this, 'roll', al, g, dt) ?? spr(sp, S_LEANR, clamp(-al * 0.0068, -0.34, 0.34) * g, 2.0, 0.48, dt);
      P[HIPS] += lp * 0.3; P[SPINE] += lp * 0.42; P[CHEST] += lp * 0.28;
      P[HIPS + 2] += lr * 0.4; P[SPINE + 2] += lr * 0.35; P[CHEST + 2] += lr * 0.25;
