  // ---------------------------------------------------------------------------------------------
  // Dances / showcase poses (kid-space feet; variants picked per character)
  // ---------------------------------------------------------------------------------------------
  _poseDance(D, name, t, dt) {
    D[WPL] = 0; D[WPR] = 0; D[STAB] = 0; D[AFOLT] = 0; D[AFOLR] = 0;
