      if (this.danceVar === 0) this._dDefeatSlump(D, t);
      else if (this.danceVar === 1) this._dDefeatSulk(D, t);
      else this._dDefeatKick(D, t);
    } else if (name === 'menu_idle') {
      this._dMenuIdle(D, t);
