      D[HIPS + 2] = -0.1 * sd * hop; D[CHEST + 2] = 0.08 * sd * hop; D[HEAD + 2] = 0.12 * sd * hop;
      setE(D, FOOTL, 0.11, ANKLE_H + 0.06 * hop * (sd > 0 ? 1 : 0.4), 0); setE(D, FOOTR, -0.11, ANKLE_H + 0.06 * hop * (sd < 0 ? 1 : 0.4), 0);
