    D[SPINE] = 0.2 - 0.1 * sigh + 0.05 * drop; D[CHEST] = 0.16 - 0.12 * sigh + 0.05 * drop; D[NECK] = 0.1; D[HEAD] = 0.2 - 0.16 * sigh + 0.1 * drop + 0.03 * sw;
