    setE(D, FOOTL, 0.095, ANKLE_H, 0.01); setE(D, FOOTR, -0.1, ANKLE_H + 0.14 * stomp, 0.03 * stomp); D[FOOTLR + 1] = 0.12; D[FOOTRR + 1] = -0.2; D[FOOTRR] = -0.2 * stomp;
