// O(az, el, off) is offset from the bare head surface; [x, y, z] are head-relative free points.
// ------------------------------------------------------------------------------------------------
const S = (az, el, extra = 0) => ['s', az, el, extra];
const IN = (az, el) => ['in', az, el];
const O = (az, el, off) => ['o', az, el, off];
