        const L = 0.05 + 0.006 * Math.max(0, Math.cos(az));
        const dir = new V3(n.x, 0, n.z).normalize().multiplyScalar(Math.cos(0.62)).add(new V3(0, -Math.sin(0.62), 0));
        q.addScaledVector(dir, Math.min(1, sN) * L);
