  const stockLow = sweep([new V3(0, 0.03, -0.09), new V3(0, 0.012, -0.16), new V3(0, 0.004, -0.228), new V3(0, 0.012, -0.252)], { seg: 8, radial: 6, capSteps: 2, radius: () => 0.0072, flat: 1.6, outward: (Pp, o) => o.set(1, 0, 0) });
